mapper.update:
update inv_transfer_detail
set delivered_quantity = #{prepared.deliveredAfter}
where detail_id = #{prepared.fact.childTransferDetailId}
  and transfer_id = #{prepared.fact.childTransferId}
  and item_type = #{prepared.fact.itemType}
  and item_id = #{prepared.fact.itemId}
  and product_id <=> #{prepared.fact.productId}
  and quantity = #{prepared.fact.requestedQuantity}
  and coalesce(delivered_quantity, 0) =
      #{prepared.deliveredBefore}
  and coalesce(received_quantity, 0) = #{prepared.receivedBefore}
  and #{prepared.quantity} > 0
  and #{prepared.deliveredAfter} <= quantity

update inv_transfer_order
set status = #{prepared.statusAfter},
    delivered_time = #{prepared.command.occurredAt},
    update_by = #{prepared.command.actorName},
    update_time = sysdate(),
    version = version + 1
where transfer_id = #{prepared.fact.childTransferId}
  and status = #{prepared.statusBefore}
  and version = #{prepared.orderVersionBefore}
  and approval_round = #{prepared.fact.reservationRound}
  and source_business_type = #{prepared.fact.sourceBusinessType}
  and source_business_id = #{prepared.fact.sourceBusinessId}
